import * as React from "react";
import * as Primitive from "@radix-ui/react-dialog";
import { AnimatePresence, LayoutGroup, motion } from "motion/react";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Dialog,
  DialogTrigger,
  DialogTitle,
  DialogDescription,
  DialogClose,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { useChoreography } from "@/lib/cojeev-motion/choreography";
export type LinearModalProps = Omit<React.ComponentProps<"div">, "title"> & {
  title: string;
  description: string;
  src: string;
  alt: string;
  eyebrow?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  variant?: "card" | "compact" | "centered";
};
/** Radix owns native modal semantics. Motion alone owns the shared surface journey. */
export function LinearModal({
  title,
  description,
  src,
  alt,
  eyebrow,
  open,
  defaultOpen = false,
  onOpenChange,
  variant = "card",
  children,
  className,
  ref,
  ...props
}: LinearModalProps) {
  const [localOpen, setLocalOpen] = React.useState(defaultOpen),
    id = React.useId();
  const { quiet, transition } = useChoreography();
  const isOpen = open ?? localOpen;
  const change = (value: boolean) => {
    if (open === undefined) setLocalOpen(value);
    onOpenChange?.(value);
  };
  // A single layout group and stable IDs connect the measured card and portal.
  // Quiet mode removes projection, while content and native semantics remain.
  const shared = (part: string) => (quiet ? undefined : `${id}-${part}`);
  const timing = quiet ? { duration: 0, delay: 0 } : transition;
  return (
    <div
      {...props}
      ref={ref}
      className={cn("v-linear-modal", className)}
      data-slot="linear-modal"
      data-variant={variant}
      data-quiet={quiet || undefined}
    >
      <LayoutGroup id={id}>
        <Dialog open={isOpen} onOpenChange={change}>
          <DialogTrigger asChild>
            <motion.button
              type="button"
              layoutId={shared("surface")}
              className="v-linear-modal__card"
              data-morph="none"
              data-flow="off"
              transition={timing}
              style={{ borderRadius: 24, opacity: isOpen ? 0 : 1 }}
              aria-label={`Read ${title}`}
            >
              <motion.img
                layoutId={shared("image")}
                transition={timing}
                className="v-linear-modal__image"
                src={src}
                alt={alt}
              />
              <span className="v-linear-modal__summary">
                {eyebrow && (
                  <span className="v-linear-modal__edition">{eyebrow}</span>
                )}
                <motion.strong layoutId={shared("title")} transition={timing}>
                  {title}
                </motion.strong>
                <span>{description}</span>
                <span className="v-linear-modal__read" aria-hidden="true">
                  Take a closer look <Icon name="plus" />
                </span>
              </span>
            </motion.button>
          </DialogTrigger>
          <AnimatePresence>
            {isOpen && (
              <Primitive.Portal forceMount>
                <Primitive.Overlay asChild forceMount>
                  <motion.div
                    className="v-linear-modal__overlay"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    transition={quiet ? { duration: 0 } : { duration: 0.2 }}
                  />
                </Primitive.Overlay>
                <Primitive.Content asChild forceMount>
                  <motion.section
                    className="v-linear-modal__detail"
                    data-variant={variant}
                    data-morph="none"
                    data-flow="off"
                    layoutId={shared("surface")}
                    transition={timing}
                    style={{ borderRadius: 28 }}
                    aria-describedby={`${id}-description`}
                  >
                    <ScrollArea
                      variant="plain"
                      type="always"
                      className="v-linear-modal__scroll"
                      aria-label="Study detail"
                      viewportProps={{ tabIndex: -1 }}
                    >
                      <motion.img
                        layoutId={shared("image")}
                        transition={timing}
                        className="v-linear-modal__hero"
                        src={src}
                        alt={alt}
                      />
                      <div className="v-linear-modal__content">
                        <DialogTitle asChild>
                          <motion.h2
                            layoutId={shared("title")}
                            transition={timing}
                          >
                            {title}
                          </motion.h2>
                        </DialogTitle>
                        <motion.div
                          initial={quiet ? false : { opacity: 0, y: 16 }}
                          animate={{ opacity: 1, y: 0 }}
                          exit={{ opacity: 0, y: quiet ? 0 : 8 }}
                          transition={
                            quiet
                              ? { duration: 0 }
                              : { duration: 0.25, delay: 0.1 }
                          }
                        >
                          <DialogDescription id={`${id}-description`}>
                            {description}
                          </DialogDescription>
                          <div className="v-linear-modal__story">
                            {children}
                          </div>
                        </motion.div>
                      </div>
                    </ScrollArea>
                    <DialogClose asChild>
                      <Button
                        className="v-linear-modal__close"
                        variant="secondary"
                        aria-label="Close detail"
                      >
                        <Icon name="x" />
                      </Button>
                    </DialogClose>
                  </motion.section>
                </Primitive.Content>
              </Primitive.Portal>
            )}
          </AnimatePresence>
        </Dialog>
      </LayoutGroup>
    </div>
  );
}

@layer cojeev-states {
.v-linear-modal {
  width: min(100%, 440px);
  min-width: 0;
}
.v-linear-modal__card {
  display: grid;
  width: 100%;
  padding: 0;
  border: 1px solid var(--v-border);
  overflow: hidden;
  text-align: left;
  background: var(--v-paper);
  color: var(--v-text);
  cursor: pointer;
}
.v-linear-modal__image {
  display: block;
  width: 100%;
  height: 240px;
  object-fit: cover;
}
.v-linear-modal__summary {
  display: grid;
  gap: 12px;
  padding: 24px;
}
.v-linear-modal__summary strong {
  font: 28px/1.1 var(--font-display);
  max-width: 15ch;
}
.v-linear-modal__summary > span {
  font: 14px/1.5 var(--font-body);
  color: var(--v-text-2);
}
.v-linear-modal__summary .v-linear-modal__edition {
  font-size: 10px;
  letter-spacing: 0.08em;
}
.v-linear-modal__summary .v-linear-modal__read {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--v-text);
  font-weight: 600;
  border-top: 1px solid var(--v-border);
  padding-top: 16px;
  margin-top: 4px;
}
.v-linear-modal__read > .v-icon {
  width: 32px;
  height: 32px;
  padding: 6px;
  border-radius: 50%;
  background: var(--v-pink);
  color: var(--ink-fixed);
}
.v-linear-modal__card:focus-visible {
  outline: 3px solid var(--v-brand);
  outline-offset: 4px;
}
.v-linear-modal__overlay {
  position: fixed;
  inset: 0;
  background: var(--v-scrim);
  z-index: var(--z-dialog);
}
.v-linear-modal__detail {
  position: fixed;
  inset: 0;
  margin: auto;
  width: min(760px, calc(100% - 40px));
  height: fit-content;
  max-height: calc(100dvh - 40px);
  overflow: hidden;
  border: 1px solid var(--v-border);
  background: var(--v-paper);
  color: var(--v-text);
  z-index: calc(var(--z-dialog) + 1);
  box-shadow: var(--shadow-float);
}
.v-linear-modal__scroll[data-slot="scroll-area"] {
  --h: calc(100dvh - 42px);
  height: auto;
  max-height: var(--h);
  background: transparent;
  border-radius: 0;
  box-shadow: none;
}
.v-linear-modal__scroll[data-slot="scroll-area"].v-scroll.-plain
  > [data-slot="scroll-area-viewport"] {
  height: auto;
  max-height: var(--h);
  padding: 0;
}
.v-linear-modal__hero {
  display: block;
  width: 100%;
  height: 320px;
  object-fit: cover;
}
.v-linear-modal__content {
  display: grid;
  gap: 18px;
  padding: 32px;
}
.v-linear-modal__content h2 {
  font: 36px/1.05 var(--font-display);
  margin: 0;
  max-width: 18ch;
}
.v-linear-modal__content [data-slot="dialog-description"] {
  margin: 0;
  line-height: 1.6;
}
.v-linear-modal__story {
  font: 15px/1.7 var(--font-body);
  margin-top: 16px;
}
.v-linear-modal__story > p + p {
  margin-top: 12px;
}
.v-linear-modal__detail .v-linear-modal__close {
  width: 44px;
  min-width: 44px;
  min-height: 44px;
  padding: 0;
  position: absolute;
  top: 16px;
  right: 16px;
}
.v-linear-modal[data-variant="compact"] .v-linear-modal__card {
  grid-template-columns: 110px 1fr;
}
.v-linear-modal[data-variant="compact"] .v-linear-modal__image {
  height: 100%;
  min-height: 190px;
}
.v-linear-modal[data-variant="compact"] .v-linear-modal__summary {
  padding: 20px;
}
.v-linear-modal[data-variant="compact"] .v-linear-modal__summary strong {
  font-size: 23px;
}
.v-linear-modal__detail[data-variant="centered"] {
  width: min(880px, calc(100% - 40px));
}
.v-linear-modal__detail[data-variant="centered"] .v-linear-modal__hero {
  width: calc(100% - 64px);
  margin: 32px auto 0;
  height: 280px;
  border-radius: 16px;
  object-fit: contain;
  background: var(--v-blue-soft);
}
.v-linear-modal__detail[data-variant="centered"] .v-linear-modal__content {
  max-width: 640px;
  margin: auto;
  text-align: center;
}
.v-linear-modal__detail[data-variant="centered"] .v-linear-modal__content h2 {
  margin: auto;
}
.v-linear-modal__detail[data-variant="centered"] .v-linear-modal__story > div {
  justify-content: center;
}
.v-linear-example {
  display: grid;
  gap: 28px;
  width: 100%;
  min-width: 0;
  padding: 18px;
  justify-items: center;
}
.v-linear-example > header {
  width: 100%;
  display: grid;
  gap: 12px;
}
.v-linear-example h3 {
  font: 26px/1.15 var(--font-display);
  max-width: 22ch;
  margin: 0;
}
.v-linear-example p {
  margin: 0;
  line-height: 1.6;
  color: var(--v-text-2);
  font-size: 14px;
}
.v-linear-example__index {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  padding: 12px;
}
.v-linear-example__index .v-btn {
  height: auto;
  min-height: 72px;
  white-space: normal;
  text-align: left;
  justify-content: start;
  gap: 12px;
}
.v-linear-example__gallery {
  width: 100%;
  min-width: 0;
}
.v-linear-example__gallery [data-slot="carousel-item"] {
  width: min(310px, 100%);
  padding: 4px;
}
.v-linear-example__gallery .v-linear-modal__summary {
  padding: 20px;
}
.v-linear-example__gallery .v-linear-modal__image {
  height: 190px;
}
.v-linear-example__gallery .v-linear-modal__summary strong {
  font-size: 25px;
  min-height: 2.2em;
}
.v-linear-example__gallery [data-slot="carousel-navigation"] {
  flex-wrap: wrap;
  padding: 12px;
}
.v-linear-example__gallery [data-slot="carousel-navigation"] > span {
  margin-right: auto;
  font-size: 12px;
  color: var(--v-text-2);
}
@media (max-width: 540px) {
  .v-linear-modal__image {
    height: 190px;
  }
  .v-linear-modal__summary {
    padding: 20px;
  }
  .v-linear-modal__hero {
    height: 220px;
  }
  .v-linear-modal__content {
    padding: 24px;
  }
  .v-linear-modal__content h2 {
    font-size: 29px;
  }
  .v-linear-modal[data-variant="compact"] .v-linear-modal__card {
    grid-template-columns: 80px 1fr;
  }
  .v-linear-example__index {
    grid-template-columns: minmax(0, 1fr);
  }
  .v-linear-example__index .v-btn {
    min-height: 44px;
  }
  .v-linear-modal__detail[data-variant="centered"] .v-linear-modal__hero {
    width: calc(100% - 32px);
    margin-top: 16px;
    height: 190px;
  }
}

}
